/*
 * mib_oids.h - OID arcs of MESTIO-GW-MIB used by the agent (private to snmp_gw; pure C).
 *
 * GWMIB_NODES lists every named node the agent serves or sends as X(name, parent, arc); the names are
 * the MIB descriptors generated by tools/gen_mib.py. tests/test_mib.py parses this list, resolves the
 * full OIDs (mestioGwMIB = 1.3.6.1.4.1.<PEN>.1) and requires each to equal the OID of the same
 * descriptor in the pysmi-compiled MIB, and every OBJECT-TYPE / NOTIFICATION-TYPE of the MIB to be
 * either listed here or a generated mexSetpointTable column (GWMIB_SP_COLUMN). Modules use only the
 * GWMIB_<name> constants below, never literal arcs. One X() per line (parsed by the test).
 */
#pragma once

#include <stdint.h>

#include "mex150/regmap.h"

/* clang-format off */
